style.css:
/* Dark Mode Styling */
body {
    background-color: #1e1e1e;
    color: #e0e0e0;
}

header {
    background-color: #333333;
    border-bottom: 3px solid #d4a017; /* Mörkare guldton */
}

nav {
    background-color: #2a2a2a;
    border-bottom: 2px solid #587b8c; /* Mörkare blåton */
}

section {
    background-color: #252525;
    border: 1px solid #465a69; /* Nedtonad blågrå */
}

footer {
    background-color: #1b3a4b;
    color: #e0e0e0;
}

/* Anpassning för knappar och länkar */
button, a {
    background-color: #465a69;
    color: #ffffff;
    border: none;
    padding: 10px 15px;
    border-radius: 5px;
    transition: background 0.3s;
}

button:hover, a:hover {
    background-color: #587b8c;
}


button:hover, a:hover {
    background-color: #587b8c;
}
